// B02 입력 검사 (P11 골격). 계약 원본: WORKFLOW-DESIGN 6.1 Request, 6.4.1, 7.4.
// 규칙으로 판정 가능한 검사만 수행하고 LLM은 호출하지 않는다(WF-08 LLM 0회).
// 미확정(팀 합의 전): codes 세부 이름, 주입 패턴 목록.
const MAX_QUESTION = 500;
const MAX_ID = 64;
const DEADLINE_MS = 20000; // 일반 응답 20초는 초기 비교값(D05 실측 전)

const body = $json.body;
const codes = [];
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const str = (v) => (typeof v === 'string' ? v.trim() : null);

let request = null;
if (!isObj(body)) {
  codes.push('body_not_object');
} else {
  const request_id = str(body.request_id);
  const user = str(body.user);
  const question = str(body.question);
  if (request_id === null || request_id.length === 0) codes.push('request_id_required');
  else if (request_id.length > MAX_ID) codes.push('request_id_too_long');
  if (user === null || user.length === 0) codes.push('user_required');
  else if (user.length > MAX_ID) codes.push('user_too_long');
  if (question === null || question.length === 0) codes.push('question_empty');
  else if (question.length > MAX_QUESTION) codes.push('question_too_long');

  let attempt = 1;
  if (body.attempt !== undefined && body.attempt !== null) {
    if (!Number.isInteger(body.attempt) || body.attempt < 1) codes.push('attempt_invalid');
    else attempt = body.attempt;
  }
  for (const key of ['channel', 'context', 'case_ref']) {
    if (body[key] !== undefined && body[key] !== null && typeof body[key] !== 'string') {
      codes.push(`${key}_invalid`);
    }
  }
  request = {
    request_id: request_id ?? '',
    user: user ?? '',
    question: question ?? '',
    channel: str(body.channel) ?? undefined,
    attempt,
    context: str(body.context) ?? undefined,
    case_ref: str(body.case_ref) ?? undefined, // 6.1·6.4.5 현행 계약
  };
}

// 명백한 주입만 차단한다. 타인 기록 요청은 권한 문제(WF-06/07)라 여기서 막지 않는다.
const INJECTION = [
  /ignore\s+(all\s+|any\s+)?(previous|prior|above)\s+(instructions|prompts?|rules)/i,
  /disregard\s+(the\s+)?(system|previous)\s+(prompt|instructions)/i,
  /(reveal|print|show)\s+(me\s+)?(the\s+|your\s+)?system\s+prompt/i,
  /you\s+are\s+now\s+(a|an|in)\s/i,
  /(developer|dan|jailbreak)\s+mode/i,
  /(이전|앞|위)의?\s*(모든\s*)?(지시|지침|명령|규칙|프롬프트)\S*\s*(을|를|은|는)?\s*(전부\s*|모두\s*)?(무시|잊어)/,
  /시스템\s*프롬프트\S*\s*(을|를)?\s*(보여|출력|알려|공개)/,
  /(너는|당신은)\s*이제(부터)?\s*.{0,20}(관리자|개발자|역할|시스템)/,
  /(관리자|운영자|개발자)\s*(권한|모드)\s*(으로|로)\s*(전환|실행|바꿔|변경)/,
  /<\s*\/?\s*(script|system|im_start|im_end)\b/i,
];
let blocked = false;
if (codes.length === 0) {
  const text = `${request.question}\n${request.context ?? ''}`;
  blocked = INJECTION.some((re) => re.test(text));
}

const now = Date.now();
const security = { blocked_by: null, reason: null, masked: 0 };
let response = null;
let status = 200;
let error_code = null;

if (codes.length > 0) {
  status = 400;
  error_code = 'invalid_input';
  response = { error: 'invalid_input', codes };
} else if (blocked) {
  status = 200;
  error_code = 'prompt_injection';
  security.blocked_by = 'B02 입력 검사';
  security.reason = 'prompt_injection';
  response = {
    request_id: request.request_id,
    route: '차단',
    answer: '요청에 처리할 수 없는 지시가 포함되어 있어 접수하지 않았습니다. 따릉이 이용 문의만 다시 보내 주세요.',
    sources: [],
    ticket: null,
    agents: [],
    security,
    reason: 'prompt_injection',
  };
}

// headers는 인증 처리 후 업무 문맥·감사에 복사하지 않는다(6.1 WebhookBody).
return {
  json: {
    request,
    input_ok: codes.length === 0 && !blocked,
    actor: null,
    security,
    response,
    status,
    error_code,
    received_at: new Date(now).toISOString(),
    deadline_at: new Date(now + DEADLINE_MS).toISOString(),
  },
};

// B05 등록·권한 확인 (P11 골격). B04 full response를 받아 서버 기준 actor를 만든다.
// 요청 본문의 자기소개(역할·권한)는 사용하지 않는다(6.1 Actor, 6.4.1).
// 형식·권한 조합·오류 코드 원본: WORKFLOW-DESIGN 6.4.1, 7.4. R04·R05 검토 대기.
const ctx = $('B02 입력 검사').item.json; // 호출 직전 문맥 복원(6.1)
const raw = $json;
const statusCode = Number(raw.statusCode ?? raw.status ?? 0);
const body = raw.body;
const ROLE_LEVELS = {
  citizen: ['public'],
  support: ['public', 'restricted'],
  security: ['public', 'restricted'],
};
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const isId = (v) => typeof v === 'string' && v.trim().length > 0;

// 권한 조합: 모든 역할은 public을 포함하고 역할별 허용 값만 중복 없이 가진다.
function validPermission(role, levels) {
  if (typeof role !== 'string' || !Object.hasOwn(ROLE_LEVELS, role)) return false;
  if (!Array.isArray(levels) || !levels.includes('public')) return false;
  if (new Set(levels).size !== levels.length) return false;
  return levels.every((level) => ROLE_LEVELS[role].includes(level));
}

// 등록 응답 → actor 또는 실패 코드. 팀 형식 {id,role,access_levels}, 과정 data-api 형식 {name,dept}만 허용.
function toActor(data, requestedUser) {
  if (!isObj(data)) return { code: 'user_lookup_invalid_response' };
  if (Object.hasOwn(data, 'id')) {
    if (!isId(data.id)) return { code: 'user_lookup_invalid_response' };
    if (data.id !== requestedUser) return { code: 'user_id_mismatch' };
    if (!validPermission(data.role, data.access_levels)) return { code: 'user_permission_invalid' };
    return { actor: { id: data.id, role: data.role, access_levels: [...data.access_levels] } };
  }
  const hasPermissionField = Object.hasOwn(data, 'role') || Object.hasOwn(data, 'access_levels');
  if (!isId(data.name) || !isId(data.dept) || hasPermissionField) {
    return { code: 'user_lookup_invalid_response' };
  }
  if (data.name !== requestedUser) return { code: 'user_id_mismatch' };
  // dept → 역할·권한 매핑은 R03/R04 확정 전이므로 승격 없이 최소 권한만 부여한다.
  return { actor: { id: data.name, role: 'citizen', access_levels: ['public'] } };
}

let actor = null;
let response = null;
let status = 200;
let error_code = null;

if (statusCode === 404) {
  status = 400;
  error_code = 'unknown_user';
  response = { error: 'unknown_user', codes: ['unknown_user'] };
} else {
  // 200 응답의 계약 위반과 조회 장애는 신원을 믿을 수 없으므로 같은 503으로 거절한다.
  const result = statusCode === 200 ? toActor(body, ctx.request.user) : { code: 'user_lookup_unavailable' };
  actor = result.actor ?? null;
  if (!actor) {
    status = 503;
    error_code = 'user_lookup_error';
    response = { error: 'user_lookup_error', codes: [result.code] };
  }
}

return { json: { ...ctx, actor, actor_ok: actor !== null, response, status, error_code } };

// M01 골격 mock: B07~B32(문맥·분류·RAG·답변·검증·티켓·저장)를 대신한다.
// P19에서 실제 노드로 교체한다. mock 통과는 실제 연동 완료가 아니다.
const ctx = $json;
return {
  json: {
    ...ctx,
    status: 200,
    error_code: null,
    response: {
      request_id: ctx.request.request_id,
      route: '담당자 이관',
      answer: '골격 시험 응답입니다. 실제 문의 접수·티켓 생성·담당자 이관은 이루어지지 않았습니다.',
      sources: [],
      ticket: null,
      agents: [],
      security: ctx.security,
      reason: 'skeleton_mock',
    },
  },
};

// B33 응답 구성 (P11 골격 범위): 거절·차단·mock 결과를 공통 응답으로 정규화한다.
// 정상 Response 형식은 과정 공통 계약, InputError={error,codes}.
const ctx = $json;
const r = ctx.response;
let body;
let status = Number.isInteger(ctx.status) ? ctx.status : 500;

if (r && typeof r.error === 'string') {
  body = { error: r.error, codes: Array.isArray(r.codes) ? r.codes : [] };
} else if (r && typeof r.route === 'string') {
  body = {
    request_id: r.request_id ?? ctx.request?.request_id ?? '',
    route: r.route,
    answer: r.answer ?? '',
    sources: Array.isArray(r.sources) ? r.sources : [],
    ticket: r.ticket ?? null,
    agents: Array.isArray(r.agents) ? r.agents : [],
    security: r.security ?? { blocked_by: null, reason: null, masked: 0 },
  };
  if (r.case_ref) body.case_ref = r.case_ref; // 6.1·6.4.5 현행 계약
  if (r.reason) body.reason = r.reason;
  body.timings = { total_ms: Math.max(0, Date.now() - Date.parse(ctx.received_at)) };
} else {
  status = 500;
  body = { error: 'protocol_error', codes: ['response_missing'] };
}

// 감사 메타: 원문 질문·답변·연락처는 남기지 않는다(7.4).
const log = {
  request_id: ctx.request?.request_id ?? null,
  node: 'B33',
  route: body.route ?? null,
  status,
  reason: body.reason ?? ctx.error_code ?? null,
  masked: body.security?.masked ?? 0,
  at: new Date().toISOString(),
};

return { json: { ...ctx, response_ready: true, http_status: status, http_body: body, log } };
